// Single-file copy for Supabase Dashboard > Edge Functions > Editor.
// Generated by: node supabase/build-account-admin-bundle.mjs
// Source: functions/account-admin/{helpers,handler,index}.ts and shared CORS/body helpers.
// Keep gateway Verify JWT OFF: this handler validates a fresh user token with Auth,
// then checks the active administrator role in service-only SQL for every action.
// Configure ALLOWED_ORIGINS with the exact website origin.
import { createClient, isAuthApiError } from 'npm:@supabase/supabase-js@2.117.2';

export const MAX_REQUEST_BYTES = 8192;

export function allowedOrigins(configured: string | undefined): Set<string> {
  const candidates = (configured ?? 'http://localhost:5173,http://127.0.0.1:5173').split(',');
  const origins = new Set<string>();
  for (const candidate of candidates) {
    try {
      const parsed = new URL(candidate.trim());
      if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') continue;
      if (parsed.username || parsed.password || parsed.search || parsed.hash) continue;
      if (parsed.pathname !== '/') continue;
      origins.add(parsed.origin);
    } catch {
      // Ignore invalid configuration entries rather than allowing wildcards.
    }
  }
  return origins;
}

export function responseHeaders(origin: string | null, origins: Set<string>): Headers {
  const headers = new Headers({
    'Cache-Control': 'no-store',
    'Content-Type': 'application/json; charset=utf-8',
    Vary: 'Origin',
  });
  if (origin && origins.has(origin)) {
    headers.set('Access-Control-Allow-Origin', origin);
    headers.set(
      'Access-Control-Allow-Headers',
      'authorization, x-client-info, apikey, content-type',
    );
    headers.set('Access-Control-Allow-Methods', 'POST, OPTIONS');
  }
  return headers;
}

export async function readBoundedJson(request: Request): Promise<unknown> {
  const length = request.headers.get('content-length');
  if (length && Number(length) > MAX_REQUEST_BYTES) throw new Error('request_too_large');
  const reader = request.body?.getReader();
  if (!reader) throw new Error('missing_body');
  const chunks: Uint8Array[] = [];
  let bytes = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      bytes += value.byteLength;
      if (bytes > MAX_REQUEST_BYTES) throw new Error('request_too_large');
      chunks.push(value);
    }
  } finally {
    await reader.cancel().catch(() => undefined);
    reader.releaseLock();
  }
  const body = new Uint8Array(bytes);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(body));
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const ADMIN_USERNAME_PATTERN = /^[a-z0-9_]{3,24}$/;

export type AccountStatus = 'active' | 'suspended';
export type AdminRequest =
  | {
      action: 'list';
      page: number;
      pageSize: number;
      search: string;
      status: AccountStatus | 'all';
    }
  | { action: 'suspend' | 'reactivate'; userId: string }
  | { action: 'delete'; userId: string; confirmation: string };

export function bearerToken(header: string | null): string | null {
  if (!header || header.length > 8192) return null;
  const match = /^Bearer ([a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+)$/i.exec(header);
  return match?.[1] ?? null;
}

export function parseAdminRequest(input: unknown): AdminRequest | null {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const value = input as Record<string, unknown>;
  if (typeof value.action !== 'string') return null;
  if (value.action === 'list') {
    if (
      Object.keys(value).some(
        (key) => !['action', 'page', 'pageSize', 'search', 'status'].includes(key),
      )
    )
      return null;
    const page = value.page === undefined ? 1 : value.page;
    const pageSize = value.pageSize === undefined ? 20 : value.pageSize;
    const search = value.search === undefined ? '' : value.search;
    const status = value.status === undefined ? 'all' : value.status;
    if (
      typeof page !== 'number' ||
      !Number.isInteger(page) ||
      page < 1 ||
      page > 100000 ||
      typeof pageSize !== 'number' ||
      !Number.isInteger(pageSize) ||
      pageSize < 1 ||
      pageSize > 50 ||
      typeof search !== 'string' ||
      search.length > 100 ||
      /[\u0000-\u001f\u007f]/.test(search) ||
      typeof status !== 'string' ||
      !['all', 'active', 'suspended'].includes(status)
    )
      return null;
    return {
      action: 'list',
      page,
      pageSize,
      search: search.trim(),
      status: status as AccountStatus | 'all',
    };
  }
  if (!['suspend', 'reactivate', 'delete'].includes(value.action)) return null;
  const keys =
    value.action === 'delete' ? ['action', 'userId', 'confirmation'] : ['action', 'userId'];
  if (Object.keys(value).some((key) => !keys.includes(key))) return null;
  if (typeof value.userId !== 'string' || !UUID_PATTERN.test(value.userId)) return null;
  if (value.action === 'delete') {
    if (typeof value.confirmation !== 'string' || !ADMIN_USERNAME_PATTERN.test(value.confirmation))
      return null;
    return { action: 'delete', userId: value.userId, confirmation: value.confirmation };
  }
  return { action: value.action as 'suspend' | 'reactivate', userId: value.userId };
}

export class AdminBackendError extends Error {
  readonly code: string;
  constructor(code: string) {
    super(code);
    this.code = code;
    this.name = 'AdminBackendError';
  }
}

export class DefiniteAuthFailure extends Error {
  constructor() {
    super('auth_operation_rejected');
    this.name = 'DefiniteAuthFailure';
  }
}

export function adminRpcError(error: { message?: string; code?: string }): AdminBackendError {
  const recognized = [
    'admin_required',
    'protected_admin',
    'account_not_found',
    'delete_in_progress',
    'account_action_in_progress',
    'invalid_confirmation',
    'invalid_status',
    'invalid_pagination',
    'invalid_search',
  ];
  const code = recognized.find((candidate) => error.message === candidate);
  return new AdminBackendError(code ?? 'admin_temporarily_unavailable');
}

export interface ManagedAccount {
  id: string;
  username: string;
  status: AccountStatus;
}

export interface AccountList {
  accounts: Array<
    ManagedAccount & {
      displayName: string;
      email: string;
      role: 'user' | 'admin';
      createdAt: string;
      lastSignInAt: string | null;
      emailConfirmed: boolean;
    }
  >;
  total: number;
  page: number;
  pageSize: number;
  stats: { total: number; active: number; suspended: number; admins: number };
}

export interface DeleteOperation {
  operationId: string;
  targetId: string;
  username: string;
}
export interface StatusOperation extends DeleteOperation {
  status: AccountStatus;
}

export interface AdminBackend {
  authenticate(token: string): Promise<string | null>;
  listAccounts(
    actorId: string,
    request: Extract<AdminRequest, { action: 'list' }>,
  ): Promise<AccountList>;
  beginStatus(actorId: string, targetId: string, status: AccountStatus): Promise<StatusOperation>;
  completeStatus(
    actorId: string,
    operationId: string,
  ): Promise<{ targetId: string; status: AccountStatus }>;
  failStatus(actorId: string, operationId: string): Promise<void>;
  banAccount(targetId: string): Promise<void>;
  unbanAccount(targetId: string): Promise<void>;
  prepareDelete(actorId: string, targetId: string, confirmation: string): Promise<DeleteOperation>;
  deleteAccount(targetId: string): Promise<void>;
  completeDelete(actorId: string, operationId: string): Promise<void>;
  failDelete(actorId: string, operationId: string): Promise<void>;
}

interface Dependencies {
  origins: Set<string>;
  configured: boolean;
  createBackend(): AdminBackend;
}

export function createAdminHandler(dependencies: Dependencies) {
  return async (request: Request): Promise<Response> => {
    const origin = request.headers.get('origin');
    const headers = responseHeaders(origin, dependencies.origins);
    const respond = (status: number, payload: Record<string, unknown>) =>
      new Response(JSON.stringify(payload), { status, headers });
    if (origin && !dependencies.origins.has(origin))
      return respond(403, { error: 'origin_not_allowed' });
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers });
    if (request.method !== 'POST') return respond(405, { error: 'method_not_allowed' });
    const token = bearerToken(request.headers.get('authorization'));
    if (!token) return respond(401, { error: 'authentication_required' });
    if (!request.headers.get('content-type')?.toLowerCase().startsWith('application/json'))
      return respond(400, { error: 'invalid_request' });
    if (!dependencies.configured) return respond(503, { error: 'admin_temporarily_unavailable' });
    let input: AdminRequest | null;
    try {
      input = parseAdminRequest(await readBoundedJson(request));
    } catch {
      return respond(400, { error: 'invalid_request' });
    }
    if (!input) return respond(400, { error: 'invalid_request' });

    try {
      const backend = dependencies.createBackend();
      // Auth validates this token against the current account. Neither JWT
      // claims nor body fields nor editable user metadata establish a role.
      const actorId = await backend.authenticate(token);
      if (!actorId) return respond(401, { error: 'authentication_required' });
      if (input.action === 'list')
        return respond(200, { ...(await backend.listAccounts(actorId, input)) });
      if (input.action === 'suspend' || input.action === 'reactivate') {
        // The private durable operation serializes changes for this account.
        // Both paths deny database access before the external Auth operation.
        const status = input.action === 'suspend' ? 'suspended' : 'active';
        const operation = await backend.beginStatus(actorId, input.userId, status);
        try {
          if (status === 'suspended') await backend.banAccount(operation.targetId);
          else await backend.unbanAccount(operation.targetId);
        } catch (error) {
          if (!(error instanceof DefiniteAuthFailure)) {
            // A lost response cannot prove that Auth rejected the operation.
            // Keep the reservation so a late response cannot overlap a retry.
            return respond(503, {
              error: 'account_action_pending',
              retryable: true,
              pending: true,
              retryAfterSeconds: 900,
              account: {
                id: operation.targetId,
                username: operation.username,
                status: 'suspended',
              },
            });
          }
          await backend.failStatus(actorId, operation.operationId).catch(() => undefined);
          return respond(503, {
            error:
              status === 'suspended'
                ? 'account_suspended_auth_pending'
                : 'account_reactivation_failed',
            retryable: true,
            account: { id: operation.targetId, username: operation.username, status: 'suspended' },
          });
        }
        try {
          // SQL rechecks current admin privileges when completing the action.
          const completed = await backend.completeStatus(actorId, operation.operationId);
          return respond(200, {
            account: {
              id: completed.targetId,
              username: operation.username,
              status: completed.status,
            },
          });
        } catch (error) {
          if (error instanceof AdminBackendError && error.code === 'admin_required') {
            await backend.failStatus(actorId, operation.operationId).catch(() => undefined);
            return respond(503, {
              error:
                status === 'suspended'
                  ? 'account_suspended_auth_pending'
                  : 'account_reactivation_failed',
              retryable: true,
              account: {
                id: operation.targetId,
                username: operation.username,
                status: 'suspended',
              },
            });
          }
          // A missing SQL response may follow a committed transaction. Do not
          // invent an account state or claim that finalization definitely failed.
          return respond(503, {
            error: 'account_status_confirmation_pending',
            retryable: true,
            pending: true,
            retryAfterSeconds: 900,
            targetId: operation.targetId,
          });
        }
      }
      if (input.action !== 'delete') return respond(400, { error: 'invalid_request' });
      const operation = await backend.prepareDelete(actorId, input.userId, input.confirmation);
      try {
        await backend.deleteAccount(operation.targetId);
      } catch (error) {
        if (!(error instanceof DefiniteAuthFailure)) {
          return respond(503, {
            error: 'account_delete_unknown',
            retryable: false,
            pending: true,
            targetId: operation.targetId,
          });
        }
        // Preparation is durable and denies data access even if Auth is down.
        // An audit failure leaves the original pending record rather than
        // incorrectly claiming the account was removed.
        await backend.failDelete(actorId, operation.operationId).catch(() => undefined);
        return respond(503, { error: 'account_delete_failed', retryable: true, suspended: true });
      }
      try {
        await backend.completeDelete(actorId, operation.operationId);
      } catch {
        return respond(503, {
          error: 'account_deleted_audit_pending',
          deleted: true,
          retryable: false,
          targetId: operation.targetId,
        });
      }
      return respond(200, { deleted: true, targetId: operation.targetId });
    } catch (error) {
      const code =
        error instanceof AdminBackendError ? error.code : 'admin_temporarily_unavailable';
      const statuses: Record<string, number> = {
        admin_required: 403,
        protected_admin: 409,
        account_not_found: 404,
        delete_in_progress: 409,
        account_action_in_progress: 409,
        invalid_confirmation: 400,
        invalid_status: 400,
        invalid_pagination: 400,
        invalid_search: 400,
      };
      return respond(statuses[code] ?? 503, {
        error: code in statuses ? code : 'admin_temporarily_unavailable',
      });
    }
  };
}

function injectedKey(mapName: string, legacyName: string): string | undefined {
  try {
    const keys = JSON.parse(Deno.env.get(mapName) ?? '{}');
    if (typeof keys.default === 'string' && keys.default) return keys.default;
  } catch {
    /* Older projects inject individual variables. */
  }
  return Deno.env.get(legacyName);
}

const projectUrl = Deno.env.get('SUPABASE_URL');
const secretKey = injectedKey('SUPABASE_SECRET_KEYS', 'SUPABASE_SERVICE_ROLE_KEY');

const boundedFetch: typeof fetch = (input, init = {}) =>
  fetch(input, {
    ...init,
    signal: init.signal
      ? AbortSignal.any([init.signal, AbortSignal.timeout(15000)])
      : AbortSignal.timeout(15000),
  });

function throwAuthFailure(error: unknown): never {
  // A received Auth HTTP error is definite rejection. Timeout, fetch failure
  // or unrecognized SDK errors are ambiguous and retain the SQL reservation.
  if (isAuthApiError(error)) throw new DefiniteAuthFailure();
  throw new Error('auth_result_unknown');
}

const handler = createAdminHandler({
  origins: allowedOrigins(Deno.env.get('ALLOWED_ORIGINS')),
  configured: Boolean(projectUrl && secretKey),
  createBackend() {
    // Never reuse a client whose auth state could change between requests.
    const admin = createClient(projectUrl!, secretKey!, {
      auth: { persistSession: false, autoRefreshToken: false },
      global: { fetch: boundedFetch },
    });
    async function rpc<T>(name: string, parameters: Record<string, unknown>): Promise<T> {
      const { data, error } = await admin.rpc(name, parameters);
      if (error) throw adminRpcError(error);
      if (!data) throw new Error('admin_unavailable');
      return data as T;
    }
    return {
      async authenticate(token) {
        const { data, error } = await admin.auth.getUser(token);
        if (error) {
          if (
            isAuthApiError(error) &&
            error.status >= 400 &&
            error.status < 500 &&
            error.status !== 429
          )
            return null;
          throw new Error('auth_validation_unavailable');
        }
        if (!data.user) return null;
        return data.user.id;
      },
      listAccounts(actorId, input) {
        return rpc<AccountList>('admin_list_accounts', {
          p_actor_id: actorId,
          p_page: input.page,
          p_page_size: input.pageSize,
          p_search: input.search,
          p_status: input.status,
        });
      },
      beginStatus(actorId, targetId, status: AccountStatus) {
        return rpc<StatusOperation>('admin_begin_account_status', {
          p_actor_id: actorId,
          p_target_id: targetId,
          p_status: status,
        });
      },
      completeStatus(actorId, operationId) {
        return rpc<{ targetId: string; status: AccountStatus }>('admin_complete_account_status', {
          p_actor_id: actorId,
          p_operation_id: operationId,
        });
      },
      async failStatus(actorId, operationId) {
        await rpc('admin_fail_account_status', {
          p_actor_id: actorId,
          p_operation_id: operationId,
          p_error_code: 'auth_status_update_failed',
        });
      },
      async banAccount(targetId) {
        const { error } = await admin.auth.admin.updateUserById(targetId, {
          ban_duration: '87600h',
        });
        if (error) throwAuthFailure(error);
      },
      async unbanAccount(targetId) {
        const { error } = await admin.auth.admin.updateUserById(targetId, { ban_duration: 'none' });
        if (error) throwAuthFailure(error);
      },
      prepareDelete(actorId, targetId, confirmation) {
        return rpc<DeleteOperation>('admin_prepare_account_delete', {
          p_actor_id: actorId,
          p_target_id: targetId,
          p_confirmation: confirmation,
        });
      },
      async deleteAccount(targetId) {
        const { error } = await admin.auth.admin.deleteUser(targetId, false);
        if (error) throwAuthFailure(error);
      },
      async completeDelete(actorId, operationId) {
        await rpc('admin_complete_account_delete', {
          p_actor_id: actorId,
          p_operation_id: operationId,
        });
      },
      async failDelete(actorId, operationId) {
        await rpc('admin_fail_account_delete', {
          p_actor_id: actorId,
          p_operation_id: operationId,
          p_error_code: 'auth_delete_failed',
        });
      },
    };
  },
});

Deno.serve(handler);
